import{_ as a,o as n,a as p,b as l}from"./app.C41L12d5.js";const r=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"缓存控制","link":"/api/SIMD-API/c_api/cache_ctrl/cache_ctrl"},{"text":"asc_get_scalar_load_cache_mode","link":"/api/SIMD-API/c_api/cache_ctrl/asc_get_scalar_load_cache_mode"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/cache_ctrl/asc_get_scalar_load_cache_mode.md","filePath":"api/SIMD-API/c_api/cache_ctrl/asc_get_scalar_load_cache_mode.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"流水类型","slug":"流水类型","link":"#流水类型"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788435672000}'),c={name:"api/SIMD-API/c_api/cache_ctrl/asc_get_scalar_load_cache_mode.md"};function e(t,s,_,i,d,o){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>asc_get_scalar_load_cache_mode</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;c_api/cache_ctrl/cache_ctrl.h&quot;</code>。</p><p>读取当前标量读（load）路径的L2 Cache管理策略，并返回<a href="../defs/enum/asc_load_l2_cache_mode.html">asc_load_l2_cache_mode</a>枚举值。</p><p>常用于临时切换策略前保存原配置，或在设置后做回读校验。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="n">asc_load_l2_cache_mode</span><span class="w"> </span><span class="n">asc_get_scalar_load_cache_mode</span><span class="p">()</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p>无</p><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>当前标量load路径的L2 Cache管理策略，类型为<a href="../defs/enum/asc_load_l2_cache_mode.html">asc_load_l2_cache_mode</a>。</p><h2 id="流水类型">流水类型<a class="header-anchor" href="#流水类型">​</a></h2><p>PIPE_S</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>本接口仅反映标量load侧策略，与标量store侧以及向量搬运接口参数中的<code>l2_cache_mode</code>无关。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>场景：GM tiling表在tile循环内被多次标量读取（每tile读<code>length</code>与<code>offset</code>）；进入循环前查询并保存当前load策略，临时切换为<code>NORMAL_FIRST_VICTIM</code>，循环结束后恢复。若tiling只读一次，可改用<code>NOTALLOC_KEEP</code>或无需切换。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__gm__</span><span class="w"> </span><span class="kt">int32_t</span><span class="o">*</span><span class="w"> </span><span class="n">tiling_gm</span><span class="p">;</span><span class="w">   </span><span class="c1">// [tile_count, len[0..n-1], off[0..n-1]]</span>
<span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">src_gm</span><span class="p">;</span>
<span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">dst_ub</span><span class="p">;</span>

<span class="c1">// 查询并保存当前标量load策略</span>
<span class="n">asc_load_l2_cache_mode</span><span class="w"> </span><span class="n">old_mode</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_get_scalar_load_cache_mode</span><span class="p">();</span>
<span class="n">asc_set_scalar_cache_mode</span><span class="p">(</span><span class="n">asc_load_l2_cache_mode</span><span class="o">::</span><span class="n">NORMAL_FIRST_VICTIM</span><span class="p">);</span>

<span class="kt">int32_t</span><span class="w"> </span><span class="n">tile_count</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">tiling_gm</span><span class="p">[</span><span class="mi">0</span><span class="p">];</span>
<span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">int32_t</span><span class="w"> </span><span class="n">tile</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">tile</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">tile_count</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">tile</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="kt">int32_t</span><span class="w"> </span><span class="n">tile_len</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">tiling_gm</span><span class="p">[</span><span class="mi">1</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">tile</span><span class="p">];</span><span class="w">              </span><span class="c1">// 每tile标量读GM</span>
<span class="w">    </span><span class="kt">int32_t</span><span class="w"> </span><span class="n">tile_off</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">tiling_gm</span><span class="p">[</span><span class="mi">1</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">tile_count</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">tile</span><span class="p">];</span><span class="w"> </span><span class="c1">// 每tile标量读GM</span>
<span class="w">    </span><span class="n">asc_copy_gm2ub_align</span><span class="p">(</span><span class="n">dst_ub</span><span class="p">,</span><span class="w"> </span><span class="n">src_gm</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">tile_off</span><span class="p">,</span><span class="w"> </span><span class="n">tile_len</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">));</span>
<span class="w">    </span><span class="c1">// ... 向量计算 ...</span>
<span class="p">}</span>

<span class="c1">// 恢复进入本段逻辑前的标量load策略</span>
<span class="n">asc_set_scalar_cache_mode</span><span class="p">(</span><span class="n">old_mode</span><span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const w=a(c,[["render",e]]);export{r as __pageData,w as default};
